<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
$adminId=require_admin();
if(!db_table_exists('destination_catalog')) redirect('upgrade.php');
$pdo=db();$upload=new UploadService(dirname(__DIR__));$ownerService=new DestinationOwnerService($pdo);$ownerReady=$ownerService->ready();$pageStyles=['assets/destination-owner.css'];
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??$_POST['destination_id']??0);
        if($action==='delete'&&$id){$pdo->prepare("UPDATE destination_catalog SET status='archived'".($ownerReady?",publication_status='suspended'":'')." WHERE id=?")->execute([$id]);flash('success','Destination archived.');redirect('admin/destinations.php');}
        if($action==='assign_member'){$ownerService->assignMembership($adminId,$id,(int)($_POST['user_id']??0),(string)($_POST['member_role']??'manager'));flash('success','Destination access assigned.');redirect('admin/destinations.php?edit='.$id);}
        if($action==='publication'){$ownerService->setPublicationStatus($adminId,$id,(string)($_POST['publication_status']??'draft'),trim((string)($_POST['note']??'')));flash('success','Publication status updated.');redirect('admin/destinations.php?edit='.$id);}
        if($action==='resolve_claim'){$ownerService->resolveClaim($adminId,(int)($_POST['claim_id']??0),(string)($_POST['decision']??'rejected'),trim((string)($_POST['resolution_note']??'')));flash('success','Destination claim resolved.');redirect('admin/destinations.php');}

        $name=trim((string)($_POST['name']??''));if($name==='')throw new InvalidArgumentException('Destination name is required.');$slug=trim((string)($_POST['slug']??''));if($slug==='')$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-'));$image=trim((string)($_POST['hero_image_url']??''));if(!empty($_FILES['hero_image']['name'])){$image=$upload->storeImage($_FILES['hero_image'],$adminId,'destinations',1400,900)??$image;}$_POST['hero_image_url']=$image;
        $featured=isset($_POST['featured'])?1:0;$sort=(int)($_POST['sort_order']??0);$publication=$ownerReady?(string)($_POST['publication_status']??'draft'):(string)($_POST['status']??'draft');
        if($id){
            if($ownerReady){$ownerService->saveListing($adminId,$id,$_POST);$pdo->prepare('UPDATE destination_catalog SET slug=?,featured=?,sort_order=? WHERE id=?')->execute([$slug,$featured,$sort,$id]);$ownerService->setTripTypes($adminId,$id,(array)($_POST['trip_types']??['multi_day']),(string)($_POST['primary_trip_type']??'multi_day'));$ownerService->setPublicationStatus($adminId,$id,$publication,'Administrator updated destination publication status.');}
            else{$hasGeo=db_column_exists('destination_catalog','latitude');$latitude=($_POST['latitude']??'')!==''?(float)$_POST['latitude']:null;$longitude=($_POST['longitude']??'')!==''?(float)$_POST['longitude']:null;$data=[$slug,$name,trim((string)($_POST['city']??'')),trim((string)($_POST['region']??'')),trim((string)($_POST['country']??'')),trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),$image,trim((string)($_POST['best_for']??'')),trim((string)($_POST['vibe']??'')),(string)($_POST['status']??'draft'),$featured,$sort];if($hasGeo){$stmt=$pdo->prepare('UPDATE destination_catalog SET slug=?,name=?,city=?,region=?,country=?,short_description=?,description=?,hero_image_url=?,best_for=?,vibe=?,status=?,featured=?,sort_order=?,latitude=?,longitude=? WHERE id=?');$stmt->execute([...$data,$latitude,$longitude,$id]);}else{$stmt=$pdo->prepare('UPDATE destination_catalog SET slug=?,name=?,city=?,region=?,country=?,short_description=?,description=?,hero_image_url=?,best_for=?,vibe=?,status=?,featured=?,sort_order=? WHERE id=?');$stmt->execute([...$data,$id]);}}
        }else{
            $latitude=($_POST['latitude']??'')!==''?(float)$_POST['latitude']:null;$longitude=($_POST['longitude']??'')!==''?(float)$_POST['longitude']:null;
            if($ownerReady){$legacy=$publication==='published'?'active':'draft';$stmt=$pdo->prepare('INSERT INTO destination_catalog (slug,name,city,region,country,address,latitude,longitude,short_description,description,hero_image_url,best_for,vibe,typical_duration,price_range,best_season,website_url,booking_url,contact_email,contact_phone,transportation_notes,official_highlights,owner_notes,status,publication_status,featured,sort_order,published_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,IF(?="published",NOW(),NULL))');$stmt->execute([$slug,$name,trim((string)($_POST['city']??'')),trim((string)($_POST['region']??'')),trim((string)($_POST['country']??'')),trim((string)($_POST['address']??'')),$latitude,$longitude,trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),$image,trim((string)($_POST['best_for']??'')),trim((string)($_POST['vibe']??'')),trim((string)($_POST['typical_duration']??'')),trim((string)($_POST['price_range']??'')),trim((string)($_POST['best_season']??'')),trim((string)($_POST['website_url']??'')),trim((string)($_POST['booking_url']??'')),trim((string)($_POST['contact_email']??'')),trim((string)($_POST['contact_phone']??'')),trim((string)($_POST['transportation_notes']??'')),trim((string)($_POST['official_highlights']??'')),trim((string)($_POST['owner_notes']??'')),$legacy,$publication,$featured,$sort,$publication]);$id=(int)$pdo->lastInsertId();$ownerService->setTripTypes($adminId,$id,(array)($_POST['trip_types']??['multi_day']),(string)($_POST['primary_trip_type']??'multi_day'));}
            else{$stmt=$pdo->prepare('INSERT INTO destination_catalog (slug,name,city,region,country,short_description,description,hero_image_url,best_for,vibe,status,featured,sort_order,latitude,longitude) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$slug,$name,trim((string)($_POST['city']??'')),trim((string)($_POST['region']??'')),trim((string)($_POST['country']??'')),trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),$image,trim((string)($_POST['best_for']??'')),trim((string)($_POST['vibe']??'')),(string)($_POST['status']??'draft'),$featured,$sort,$latitude,$longitude]);$id=(int)$pdo->lastInsertId();}
        }
        flash('success','Destination saved.');redirect('admin/destinations.php?edit='.$id);
    }catch(Throwable $e){flash('error',$e->getMessage());redirect('admin/destinations.php'.($id?'?edit='.$id:''));}
}
$edit=null;if(isset($_GET['edit'])){$stmt=$pdo->prepare('SELECT * FROM destination_catalog WHERE id=?');$stmt->execute([(int)$_GET['edit']]);$edit=$stmt->fetch()?:null;}
$tripRows=$edit&&$ownerReady?$ownerService->tripTypes((int)$edit['id']):[];$selectedTypes=[];$primaryType='multi_day';foreach($tripRows as $tr){$selectedTypes[]=$tr['trip_type'];if($tr['is_primary'])$primaryType=$tr['trip_type'];}
if($ownerReady){$rows=$pdo->query("SELECT d.*,(SELECT CONCAT(COALESCE(u.display_name,u.email),'|',u.id) FROM destination_memberships dm JOIN users u ON u.id=dm.user_id WHERE dm.destination_catalog_id=d.id AND dm.member_role='owner' AND dm.status='active' LIMIT 1) owner_info,(SELECT GROUP_CONCAT(dt.trip_type ORDER BY dt.sort_order SEPARATOR ',') FROM destination_trip_types dt WHERE dt.destination_catalog_id=d.id) trip_types_csv FROM destination_catalog d ORDER BY d.publication_status='published' DESC,d.featured DESC,d.sort_order,d.name")->fetchAll();$users=$pdo->query("SELECT id,email,display_name,account_type FROM users WHERE status='active' ORDER BY COALESCE(display_name,email) LIMIT 500")->fetchAll();$claims=$ownerService->pendingClaims();}else{$rows=$pdo->query('SELECT * FROM destination_catalog ORDER BY status="active" DESC,featured DESC,sort_order,name')->fetchAll();$users=[];$claims=[];}
$success=flash('success');$error=flash('error');$title='Destinations — Admin';require __DIR__.'/../partials/header.php';
?>
<section class="dashboard"><div class="shell"><div class="dashboard-head"><div><div class="eyebrow">Admin · Destinations</div><h1>Destination catalog</h1><p class="muted">Manage public destination records, owner/manager access, trip placement, publishing state, and ownership claims.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="button primary small" href="<?=e(app_url('admin/destination-ai-create.php'))?>">AI Create Destination</a><a class="button secondary small" href="<?=e(app_url('destinations.php'))?>">View listing</a></div></div><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(!$ownerReady):?><div class="alert warning">Run System Upgrade to enable destination owners, managers, claims, trip types, publishing workflow, and audit history.</div><?php endif;?>
