Price range<input class="input" name="price_range" value="<?=e((string)($edit['price_range']??''))?>"></label></div><label>Best season<input class="input" name="best_season" value="<?=e((string)($edit['best_season']??''))?>"></label><div class="form-grid two"><label>Website URL<input class="input" type="url" name="website_url" value="<?=e((string)($edit['website_url']??''))?>"></label><label>Booking URL<input class="input" type="url" name="booking_url" value="<?=e((string)($edit['booking_url']??''))?>"></label></div><div class="form-grid two"><label>Contact email<input class="input" type="email" name="contact_email" value="<?=e((string)($edit['contact_email']??''))?>"></label><label>Contact phone<input class="input" name="contact_phone" value="<?=e((string)($edit['contact_phone']??''))?>"></label></div><label>Transportation / parking<textarea class="input" name="transportation_notes" rows="3"><?=e((string)($edit['transportation_notes']??''))?></textarea></label><label>Official highlights<textarea class="input" name="official_highlights" rows="3"><?=e((string)($edit['official_highlights']??''))?></textarea></label><label>Private owner notes<textarea class="input" name="owner_notes" rows="3"><?=e((string)($edit['owner_notes']??''))?></textarea></label><fieldset><legend>Trip placement</legend><?php foreach($ownerService->tripTypeCatalog() as $key=>$def):?><label class="check-row"><input type="checkbox" name="trip_types[]" value="<?=e($key)?>" <?=in_array($key,$selectedTypes,true)?'checked':''?>> <?=e($def['label'])?> <input type="radio" name="primary_trip_type" value="<?=e($key)?>" <?=$primaryType===$key?'checked':''?>> <small>Primary</small></label><?php endforeach;?></fieldset><?php endif;?><label>Hero image URL<input class="input" name="hero_image_url" value="<?=e($edit['hero_image_url']??'')?>"></label><label>Or upload hero image<input class="input" type="file" name="hero_image" accept="image/jpeg,image/png,image/webp"></label><div class="form-grid"><label><?= $ownerReady?'Publication':'Status' ?><select class="input" name="<?=$ownerReady?'publication_status':'status'?>"><?php $statuses=$ownerReady?$ownerService->publicationCatalog():['draft'=>'Draft','active'=>'Active','archived'=>'Archived'];foreach($statuses as $s=>$label):?><option value="<?=e($s)?>" <?=($ownerReady?($edit['publication_status']??'draft'):($edit['status']??'active'))===$s?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>Sort order<input class="input" type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label></div><label class="check-row"><input type="checkbox" name="featured" <?=!empty($edit['featured'])?'checked':''?>> Featured destination</label><button class="button primary">Save destination</button></form>
