reach($users as $u):?><option value="<?=(int)$u['id']?>"><?=e(($u['display_name']?:$u['email']).' · '.$u['email'])?></option><?php endforeach;?></select><select class="input" name="member_role"><option value="owner">Owner</option><option value="manager">Manager</option></select><button class="button secondary small">Assign</button></form></td></tr><?php endif;?><?php endforeach;?></tbody></table></div></div>
